import pathlib,json,hashlib,collections,html,base64,zipfile
R=pathlib.Path(__file__).resolve().parent
load=lambda n:json.loads((R/n).read_text())
parent=load('parent/review-results.json'); visual={}
for f in sorted(R.glob('visual-*.json')):
 d=json.loads(f.read_text());rows=d.get('reviews',d.get('items'))
 for x in rows:
  assert x['id'] not in visual;visual[x['id']]={'file':f.name,'findings':x}
pack={e['id']:e for e in load('packaging-results.json')};browser=load('smoke-results.json');motion={e['id']:e for e in load('motion-results.json')};archives={e['id']:e for e in load('archive-results.json')}
ids=[e['id'] for e in parent['entries']];assert len(ids)==len(set(ids))==25 and set(ids)==set(visual)==set(pack)
entries=[]
for p in parent['entries']:
 s=p['id'];hold=s in parent['visual_holds']; checks=[x for x in browser if x['id']==s]
 assert len(checks)==2 and all(x['result']=='pass' and x['sha256']==p['viewer']['sha256'] for x in checks)
 assert motion[s]['exit_code']==0
 rationale='Preserve substantive parent art-decision hold despite any more permissive independent recommendation; no user approval or changed art resolves it.' if hold else 'Candidate with disclosed finish limitations, not final user approval.'
 if s=='india':rationale+=' Lead inspected full original runtime and promotional images: both retain coral/salmon flower and green rim; peach/pink intensity and segmented rim joins are disclosed finish limitations, not established substantive redesign or malfunction. Delegated needs-user-review recommendation retained below, not erased.'
 entries.append({'id':s,'verdict':'needs-user-review' if hold else 'candidate-with-limitations','parent_status':p['status'],'parent_quality':p['quality'],'parent_decision':p['decision'],'adjudication':rationale,'independent_visual':visual[s],'viewer':p['viewer'],'selection':p['selection'],'marketing':p['marketing'],'source_models':pack[s]['models'],'source_archives':pack[s]['archives'],'source_archive_check':archives[s],'packaging_hold':pack[s]['packaging']=='hold','parent_missing_gates_preserved':p['parent_missing_gates_preserved'],'remaining_gates':p['remaining_gates'],'original_capture_paths':['parent/smoke/'+s+'/'+n+'.png' for n in ['desktop-closed','desktop-open','mobile-closed','mobile-open']],'fresh_browser':checks,'fresh_motion':motion[s],'art_changed':False,'user_final_approved':False,'launch_ready':False,'fresh_blender_reopen':False,'fresh_collision_sampling':False,'fresh_corrupt_glb_fallback':False,'fresh_nojs':False,'critical_reproducible_defects':[]})
d={'task':'t_bb053438','parent_commit':'d1becdc7366b9781a65d29712553b77fa8355059','reviewed':len(entries),'counts':dict(collections.Counter(e['verdict'] for e in entries)),'visual_holds':[e['id'] for e in entries if e['verdict']=='needs-user-review'],'packaging_holds':[e['id'] for e in entries if e['packaging_hold']],'unreviewed_ids':[],'final_approvals':0,'art_changed':False,'launch_ready':False,'method':'Five read-only visual reviewers inspected 100 immutable final parent full-resolution captures plus 25 matching marketing images. Lead adjudicated India at full resolution. Parent image hashes reverified against committed inventory; no reviewed capture overwritten. Fresh browser captures are separate evidence, not substituted into the reviewed parent capture set.','limitations':['No fresh Blender source reopening/parity or collision sampling; historical evidence remains historical.','No fresh corrupt-GLB or no-JS fallback; parent evidence preserved only.','Shared Albania endpoint assertions against each original motion module, not per-design original suites.','Mobile emulation, not physical-phone performance.','Hinge attachment ambiguity from stills is not demonstrated detachment.','Morocco partial unapproved candidate; exact-byte archive failure preserved. All final artwork, storage and release gates remain.'],'tests_run':{'parent_evidence_hashes':315,'parent_delivery_zip_members':sum(x['members_verified'] for x in load('input-verification.json')['parent_delivery_zip_readbacks']),'offline_desktop_mobile':len(browser),'shared_motion_suites':len(motion),'source_archive_inventory_members':sum(x['inventory_entries_checked'] for x in archives.values())},'entries':entries}
(R/'reviewed-ledger.json').write_text(json.dumps(d,indent=2)+'\n')
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QA ART-06 — candidate review</title><style>body{background:#131719;color:#eee;font:16px system-ui;margin:auto;padding:24px;max-width:1200px}img{width:100%;height:auto}article{border-top:1px solid #777;margin-top:32px;padding-top:16px}p{line-height:1.5}h2{color:#e2bb78}</style><h1>Batch 6 · Independent candidate review</h1><p>25 reviewed · 10 candidates with limitations · 15 user-decision holds. No final approvals. Morocco retains a separate exact-byte archive hold. Illustrations and actual-model captures are labeled; screenshots are immutable final parent evidence.</p><p>Fresh offline controls passed for desktop/mobile across all 25. No fresh Blender, collision or corrupt-model fallback certification. No artwork changed, minted, sold or deployed.</p>']
for e in entries:
 b=(R/'parent/boards'/ (e['id']+'.jpg')).read_bytes()
 parts.append('<article><h2>'+html.escape(e['id'])+' — '+e['verdict']+'</h2><img alt="Labeled marketing and desktop/mobile model comparison for '+e['id']+'" src="data:image/jpeg;base64,'+base64.b64encode(b).decode()+'"><p>'+html.escape(e['parent_decision'])+'</p><p>'+html.escape(e['adjudication'])+'</p></article>')
parts.append('</html>');(R/'review.html').write_text('\n'.join(parts),encoding='utf-8')
(R/'README.md').write_text('# QA-ART-06\n\nIndependent bounded review of all 25 unchanged candidates. 10 candidates with limitations; 15 retained user-decision holds. No final approvals. Morocco exact-byte archive hold retained.\n\nSee reviewed-ledger.json for every ID, exact source refs/hashes, independent visual observations, adjudication, fresh checks and historical-only gates. Parent captures remain immutable under parent/smoke; fresh runtime captures are under smoke. The report embeds parent comparison boards, not refreshed runtime captures.\n\nReproduce fresh checks: python prepare.py; python archive_checks.py; python motion_checks.py; python smoke_viewers.py --ids <the 25 ledger IDs>. Run from repository with immutable Git objects and the recorded profile-local viewers/archives available. These scripts are machine-local evidence harnesses, not a portable art recovery package.\n\nNo new art/source ZIP is claimed. Original source archives were independently read back with 1,385 internal inventory entries checked. Morocco required selected payload exact-byte failure remains; do not treat internal inventory consistency as selected-source equivalence.\n\nRecommended next step: downstream consolidation must retain every visual/packaging hold and final user approval/storage/release gate.\n')
print(json.dumps({k:d[k] for k in ['reviewed','counts','visual_holds','packaging_holds','tests_run']},indent=2))
